export function resolveAiGatewaySidebarConfig(options: AiGatewaySidebarOptions | false | undefined, defaultActiveItem: string = defaultAiGatewaySidebarConfig.activeItem): AiGatewaySidebarConfig | null {
    if (options === false)
        return null;
    return {
        ...defaultAiGatewaySidebarConfig,
        ...options,
        activeItem: options?.activeItem ?? defaultActiveItem,
        workspace: {
            ...defaultAiGatewaySidebarConfig.workspace,
            ...options?.workspace,
        },
        groups: options?.groups ?? defaultAiGatewaySidebarConfig.groups,
        account: {
            ...defaultAiGatewaySidebarConfig.account,
            ...options?.account,
        },
