        <NavItemLeading>
          <Icon aria-hidden size={16} strokeWidth={1.5}/>
        </NavItemLeading>
        <NavItemContent>
          <NavItemLabel>{item.label}</NavItemLabel>
        </NavItemContent>
      </NavItemTrigger>
    </NavItem>);
}
