    return (<>
      <SidebarHeader className="px-2 py-1.5">
        <SidebarIdentityRow as={onWorkspaceSelect ? "button" : "div"} className="px-1.5" leading={<SidebarIdentityAvatar className="rounded-xl bg-inverse-background text-fg-on-inverse">
              {config.workspace.avatarLabel ? config.workspace.avatarLabel : <WorkspaceIcon aria-hidden size={16} strokeWidth={1.5}/>}
            </SidebarIdentityAvatar>} onClick={onWorkspaceSelect} primary={config.workspace.name} trailing={onWorkspaceSelect ? <SwitchIcon aria-hidden size={14} strokeWidth={1.5}/> : undefined} trailingPlacement="edge"/>
      </SidebarHeader>

      <SidebarContent contentClassName="gap-3 px-2 py-1">
        {config.groups.map((group) => (<SidebarGroup key={group.id}>
            {group.label ? <SidebarGroupLabel>{group.label}</SidebarGroupLabel> : null}
            <SidebarGroupContent>
              <NavMenu activeValue={config.activeItem} aria-label={group.label ?? config.ariaLabel} keyboardNavigation="roving">
                {group.items.map((item) => (<GatewayNavigationItem item={item} key={item.id} onSelect={onNavigationSelect}/>))}
              </NavMenu>
            </SidebarGroupContent>
          </SidebarGroup>))}
      </SidebarContent>

      <SidebarFooter className="px-2 py-1.5">
        <SidebarIdentityRow as={onAccountSelect ? "button" : "div"} className="px-1.5" description={config.account.description} leading={<SidebarIdentityAvatar>{config.account.avatarLabel ?? config.account.name.slice(0, 1)}</SidebarIdentityAvatar>} onClick={onAccountSelect} primary={config.account.name} trailing={onAccountSelect ? <MoreIcon aria-hidden size={16} strokeWidth={1.5}/> : undefined} trailingPlacement="edge"/>
      </SidebarFooter>
    </>);
}
export function AiGatewayWorkspaceSidebar({ actions, config, }: {
    actions?: AiGatewaySidebarActions;
    config: AiGatewaySidebarConfig;
}) {
    return (<Sidebar ariaLabel={config.ariaLabel} className="relative !h-full" collapsible="offcanvas" mobileWidth="min(280px, calc(100vw - 24px))" width="280px">
      <GatewaySidebarNavigation config={config} {...actions}/>
