import type { AiGatewayLatencyBucket, AiGatewayMetricSeries, AiGatewayOverviewData, AiGatewayOverviewRange, AiGatewayProviderUsage, AiGatewayTimeSeriesPoint, } from "./ai-gateway-overview-types";
const DAY_MS = 86400000;
const rangeDays: Record<AiGatewayOverviewRange, number> = {
    "1d": 1,
    "7d": 7,
    "30d": 30,
    "90d": 90,
};
const providerProfiles = [
    { id: "openai", name: "OpenAI", share: 0.46 },
    { id: "anthropic", name: "Anthropic", share: 0.29 },
    { id: "google", name: "Google", share: 0.16 },
    { id: "mistral", name: "Mistral", share: 0.09 },
] as const;
function round(value: number, digits = 0) {
    const factor = 10 ** digits;
    return Math.round(value * factor) / factor;
}
function buildTimeSeries(range: AiGatewayOverviewRange, to: Date): AiGatewayTimeSeriesPoint[] {
    const days = rangeDays[range];
    const points = range === "1d" ? 24 : range === "7d" ? 28 : range === "30d" ? 30 : 45;
    const interval = (days * DAY_MS) / points;
    return Array.from({ length: points }, (_, index) => {
        const progress = index / Math.max(1, points - 1);
        const wave = Math.sin(index * 0.78) * 0.18 + Math.cos(index * 0.31) * 0.1;
        const launchPeak = Math.exp(-((progress - 0.84) ** 2) / 0.012) * 2.8;
        const requestCount = Math.max(0, Math.round(3 + days / 8 + wave * 8 + launchPeak * 8));
        const errorCount = index % 9 === 3 ? Math.max(1, Math.round(requestCount * 0.18)) : 0;
        const inputTokens = Math.round(requestCount * (1680 + (index % 5) * 210));
        const outputTokens = Math.round(requestCount * (760 + (index % 4) * 140));
        const timestamp = new Date(to.getTime() - (points - 1 - index) * interval);
        return {
            timestamp: timestamp.toISOString(),
            requestCount,
            costMicros: Math.round(inputTokens * 0.12 + outputTokens * 0.45),
            inputTokens,
            outputTokens,
            errorCount,
            errorRate: requestCount === 0 ? null : errorCount / requestCount,
            p95LatencyMs: requestCount === 0
                ? null
                : Math.round(1280 + Math.abs(Math.sin(index * 0.52)) * 2700 + launchPeak * 1900),
        };
    });
}
function buildProviders(requests: number, costMicros: number): AiGatewayProviderUsage[] {
    return providerProfiles.map((provider, index) => ({
        id: provider.id,
        name: provider.name,
        requestCount: index === providerProfiles.length - 1
            ? Math.max(0, requests -
                providerProfiles
                    .slice(0, -1)
                    .reduce((sum, item) => sum + Math.round(requests * item.share), 0))
            : Math.round(requests * provider.share),
        costMicros: Math.round(costMicros * provider.share),
    }));
}
function buildMetrics(series: AiGatewayTimeSeriesPoint[]): AiGatewayMetricSeries[] {
    const templates = [
        { id: "cache-hit", label: "Cache hit rate", aggregation: "Average", unit: "%" },
        { id: "ttft", label: "Time to first token", aggregation: "p95", unit: "ms" },
        { id: "tokens-per-request", label: "Tokens per request", aggregation: "Average", unit: "" },
    ] as const;
    return templates.map((template) => {
        const points = series.map((point, index) => {
            let value: number | null;
            if (template.id === "cache-hit") {
                value = round(56 + Math.sin(index * 0.45) * 12 + (index % 5), 1);
            }
            else if (template.id === "ttft") {
                value = point.p95LatencyMs === null ? null : Math.round(point.p95LatencyMs * 0.23);
            }
            else {
                value =
                    point.requestCount === 0
                        ? null
                        : Math.round((point.inputTokens + point.outputTokens) / point.requestCount);
            }
            return { timestamp: point.timestamp, value };
        });
        return {
            ...template,
            currentValue: points.at(-1)?.value ?? null,
            points,
        };
    });
}
const latencyDistribution: AiGatewayLatencyBucket[] = [
    { id: "0-250", lowerMs: 0, upperMs: 250, count: 5 },
    { id: "250-500", lowerMs: 250, upperMs: 500, count: 12 },
    { id: "500-1000", lowerMs: 500, upperMs: 1000, count: 23 },
    { id: "1000-2000", lowerMs: 1000, upperMs: 2000, count: 36 },
    { id: "2000-4000", lowerMs: 2000, upperMs: 4000, count: 18 },
    { id: "4000-8000", lowerMs: 4000, upperMs: 8000, count: 9 },
    { id: "8000+", lowerMs: 8000, upperMs: null, count: 4 },
];
export function createAiGatewayOverviewDemoData(range: AiGatewayOverviewRange = "30d"): AiGatewayOverviewData {
    const to = new Date("2026-09-10T10:00:00.000Z");
    const days = rangeDays[range];
    const timeSeries = buildTimeSeries(range, to);
    const requests = timeSeries.reduce((sum, point) => sum + point.requestCount, 0);
    const costMicros = timeSeries.reduce((sum, point) => sum + point.costMicros, 0);
    const inputTokens = timeSeries.reduce((sum, point) => sum + point.inputTokens, 0);
    const outputTokens = timeSeries.reduce((sum, point) => sum + point.outputTokens, 0);
    const errors = timeSeries.reduce((sum, point) => sum + point.errorCount, 0);
    const validLatencies = timeSeries
        .map((point) => point.p95LatencyMs)
        .filter((value): value is number => value !== null)
        .sort((a, b) => a - b);
    return {
        window: {
            range,
            from: new Date(to.getTime() - days * DAY_MS).toISOString(),
            to: to.toISOString(),
            granularity: range === "1d" || range === "7d" ? "hour" : "day",
            timeZone: "UTC",
            currency: "USD",
            generatedAt: to.toISOString(),
        },
        summary: {
            requests,
            costMicros,
            inputTokens,
            outputTokens,
            errors,
            errorRate: requests === 0 ? 0 : errors / requests,
            p50LatencyMs: validLatencies[Math.floor(validLatencies.length * 0.5)] ?? null,
            p95LatencyMs: validLatencies[Math.floor(validLatencies.length * 0.95)] ?? null,
            p99LatencyMs: validLatencies[Math.floor(validLatencies.length * 0.99)] ?? null,
        },
        timeSeries,
        providers: buildProviders(requests, costMicros),
        latencyDistribution,
        metrics: buildMetrics(timeSeries),
        slowestOperations: [
            { id: "chat-completions", name: "Chat completions", kind: "OpenAI", p95LatencyMs: 8482 },
            { id: "messages", name: "Messages", kind: "Anthropic", p95LatencyMs: 6110 },
            { id: "generate-content", name: "Generate content", kind: "Google", p95LatencyMs: 4920 },
        ],
        topUsers: [],
    };
}
export const aiGatewayOverviewDemoData = createAiGatewayOverviewDemoData("30d");

import type { AiGatewayOverviewData, AiGatewayOverviewRange, } from "./ai-gateway-overview-types";
const ranges = new Set<AiGatewayOverviewRange>(["1d", "7d", "30d", "90d"]);
function fail(path: string, expectation: string): never {
    throw new TypeError(`Invalid AI gateway overview data at ${path}: expected ${expectation}.`);
}
function record(value: unknown, path: string): Record<string, unknown> {
    if (typeof value !== "object" || value === null || Array.isArray(value)) {
        return fail(path, "an object");
    }
    return value as Record<string, unknown>;
}
function array(value: unknown, path: string): unknown[] {
    if (!Array.isArray(value))
        return fail(path, "an array");
    return value;
}
function string(value: unknown, path: string): string {
    if (typeof value !== "string" || value.trim().length === 0) {
        return fail(path, "a non-empty string");
    }
    return value;
}
function finiteNumber(value: unknown, path: string): number {
    if (typeof value !== "number" || !Number.isFinite(value)) {
        return fail(path, "a finite number");
    }
    return value;
}
function nonNegativeNumber(value: unknown, path: string): number {
    const result = finiteNumber(value, path);
    if (result < 0)
        return fail(path, "a non-negative number");
    return result;
}
function nonNegativeInteger(value: unknown, path: string): number {
    const result = nonNegativeNumber(value, path);
    if (!Number.isInteger(result))
        return fail(path, "a non-negative integer");
    return result;
}
function nullableNonNegativeNumber(value: unknown, path: string): number | null {
    return value === null ? null : nonNegativeNumber(value, path);
}
function rate(value: unknown, path: string): number {
    const result = finiteNumber(value, path);
    if (result < 0 || result > 1)
        return fail(path, "a number between 0 and 1");
    return result;
}
function nullableRate(value: unknown, path: string): number | null {
    return value === null ? null : rate(value, path);
}
function timestamp(value: unknown, path: string): string {
    const result = string(value, path);
    if (!/T.*(?:Z|[+-]\d{2}:\d{2})$/.test(result) || Number.isNaN(Date.parse(result))) {
        return fail(path, "an ISO 8601 timestamp with a time-zone offset");
    }
    return result;
}
function uniqueIds(items: unknown[], path: string) {
    const seen = new Set<string>();
    items.forEach((item, index) => {
        const id = string(record(item, `${path}[${index}]`).id, `${path}[${index}].id`);
        if (seen.has(id))
            fail(`${path}[${index}].id`, "a unique ID within the collection");
        seen.add(id);
    });
}
function validateWindow(value: unknown) {
    const item = record(value, "window");
    const range = string(item.range, "window.range");
    if (!ranges.has(range as AiGatewayOverviewRange)) {
        fail("window.range", 'one of "1d", "7d", "30d", or "90d"');
    }
    const from = timestamp(item.from, "window.from");
    const to = timestamp(item.to, "window.to");
    if (Date.parse(from) >= Date.parse(to))
        fail("window", "from to be earlier than to");
    const granularity = string(item.granularity, "window.granularity");
    if (granularity !== "hour" && granularity !== "day") {
        fail("window.granularity", '"hour" or "day"');
    }
    const timeZone = string(item.timeZone, "window.timeZone");
    try {
        new Intl.DateTimeFormat("en", { timeZone });
    }
    catch {
        fail("window.timeZone", "a valid IANA time-zone name");
    }
    if (!/^[A-Z]{3}$/.test(string(item.currency, "window.currency"))) {
        fail("window.currency", "a three-letter ISO 4217 currency code");
    }
    timestamp(item.generatedAt, "window.generatedAt");
}
function validateSummary(value: unknown) {
    const item = record(value, "summary");
    nonNegativeInteger(item.requests, "summary.requests");
    nonNegativeInteger(item.costMicros, "summary.costMicros");
    nonNegativeInteger(item.inputTokens, "summary.inputTokens");
    nonNegativeInteger(item.outputTokens, "summary.outputTokens");
    nonNegativeInteger(item.errors, "summary.errors");
    rate(item.errorRate, "summary.errorRate");
    nullableNonNegativeNumber(item.p50LatencyMs, "summary.p50LatencyMs");
    nullableNonNegativeNumber(item.p95LatencyMs, "summary.p95LatencyMs");
    nullableNonNegativeNumber(item.p99LatencyMs, "summary.p99LatencyMs");
}
function validateTimeSeries(value: unknown) {
    const items = array(value, "timeSeries");
    let previousTimestamp = Number.NEGATIVE_INFINITY;
    items.forEach((value, index) => {
        const path = `timeSeries[${index}]`;
        const item = record(value, path);
        const currentTimestamp = Date.parse(timestamp(item.timestamp, `${path}.timestamp`));
        if (currentTimestamp <= previousTimestamp) {
            fail(`${path}.timestamp`, "timestamps in ascending order");
        }
        previousTimestamp = currentTimestamp;
        nonNegativeInteger(item.requestCount, `${path}.requestCount`);
        nonNegativeInteger(item.costMicros, `${path}.costMicros`);
        nonNegativeInteger(item.inputTokens, `${path}.inputTokens`);
        nonNegativeInteger(item.outputTokens, `${path}.outputTokens`);
        nonNegativeInteger(item.errorCount, `${path}.errorCount`);
        nullableRate(item.errorRate, `${path}.errorRate`);
        nullableNonNegativeNumber(item.p95LatencyMs, `${path}.p95LatencyMs`);
    });
}
function validateProviders(value: unknown) {
    const items = array(value, "providers");
    uniqueIds(items, "providers");
    items.forEach((value, index) => {
        const path = `providers[${index}]`;
        const item = record(value, path);
        string(item.name, `${path}.name`);
        nonNegativeInteger(item.requestCount, `${path}.requestCount`);
        nonNegativeInteger(item.costMicros, `${path}.costMicros`);
    });
}
function validateLatencyDistribution(value: unknown) {
    const items = array(value, "latencyDistribution");
    uniqueIds(items, "latencyDistribution");
    items.forEach((value, index) => {
        const path = `latencyDistribution[${index}]`;
        const item = record(value, path);
        const lower = nonNegativeNumber(item.lowerMs, `${path}.lowerMs`);
        const upper = nullableNonNegativeNumber(item.upperMs, `${path}.upperMs`);
        if (upper !== null && upper <= lower)
            fail(`${path}.upperMs`, "a value greater than lowerMs");
        nonNegativeInteger(item.count, `${path}.count`);
    });
}
function validateMetrics(value: unknown) {
    const items = array(value, "metrics");
    uniqueIds(items, "metrics");
    items.forEach((value, index) => {
        const path = `metrics[${index}]`;
        const item = record(value, path);
        string(item.label, `${path}.label`);
        string(item.aggregation, `${path}.aggregation`);
        if (typeof item.unit !== "string")
            fail(`${path}.unit`, "a string");
        if (item.currentValue !== null)
            finiteNumber(item.currentValue, `${path}.currentValue`);
        const points = array(item.points, `${path}.points`);
        let previousTimestamp = Number.NEGATIVE_INFINITY;
        points.forEach((value, pointIndex) => {
            const pointPath = `${path}.points[${pointIndex}]`;
            const point = record(value, pointPath);
            const currentTimestamp = Date.parse(timestamp(point.timestamp, `${pointPath}.timestamp`));
            if (currentTimestamp <= previousTimestamp) {
                fail(`${pointPath}.timestamp`, "timestamps in ascending order");
            }
            previousTimestamp = currentTimestamp;
            if (point.value !== null)
                finiteNumber(point.value, `${pointPath}.value`);
        });
    });
}
function validateSlowestOperations(value: unknown) {
    const items = array(value, "slowestOperations");
    uniqueIds(items, "slowestOperations");
    items.forEach((value, index) => {
        const path = `slowestOperations[${index}]`;
        const item = record(value, path);
        string(item.name, `${path}.name`);
        string(item.kind, `${path}.kind`);
        nonNegativeNumber(item.p95LatencyMs, `${path}.p95LatencyMs`);
    });
}
function validateTopUsers(value: unknown) {
    const items = array(value, "topUsers");
    uniqueIds(items, "topUsers");
    items.forEach((value, index) => {
        const path = `topUsers[${index}]`;
        const item = record(value, path);
        string(item.label, `${path}.label`);
        nonNegativeInteger(item.requestCount, `${path}.requestCount`);
    });
}
/** Validates an exact API response before it reaches the rendering layer. */
export function parseAiGatewayOverviewData(value: unknown): AiGatewayOverviewData {
    const input = record(value, "root");
    validateWindow(input.window);
    validateSummary(input.summary);
    validateTimeSeries(input.timeSeries);
    validateProviders(input.providers);
    validateLatencyDistribution(input.latencyDistribution);
    validateMetrics(input.metrics);
